import{_ as t,o as d,c as o,ae as r}from"./chunks/framework.YL6nI5ZP.js";const m=JSON.parse('{"title":"Scripts, benchmarks y verificación","description":"","frontmatter":{},"headers":[],"relativePath":"es/reference/07-scripts-y-benchmarks.md","filePath":"es/reference/07-scripts-y-benchmarks.md"}'),a={name:"es/reference/07-scripts-y-benchmarks.md"};function s(c,e,n,i,l,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="scripts-benchmarks-y-verificacion" tabindex="-1">Scripts, benchmarks y verificación <a class="header-anchor" href="#scripts-benchmarks-y-verificacion" aria-label="Permalink to &quot;Scripts, benchmarks y verificación&quot;">​</a></h1><p>Los 15 scripts <code>.mjs</code> en <code>scripts/</code> más los dos scripts de build de shell — qué hace cada uno y cómo ejecutarlo.</p><p>Todos se ejecutan desde la raíz del repo con <code>node scripts/&lt;name&gt;.mjs</code>. El patrón común: shim de <code>globalThis.self/window</code>, cargar <code>public/openswmm2d.js</code>, instanciar <code>openswmm2d.wasm</code> sincrónicamente en Node, envolver la API C con <code>Module.cwrap</code>. Varios levantan <code>server.py</code> + una instancia de Chrome vía CDP.</p><h2 id="benchmarks-y-probes-motor-en-node" tabindex="-1">Benchmarks y probes (motor en Node) <a class="header-anchor" href="#benchmarks-y-probes-motor-en-node" aria-label="Permalink to &quot;Benchmarks y probes (motor en Node)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Propósito</th><th>Uso</th></tr></thead><tbody><tr><td><code>bench-1d-bellinge.mjs</code></td><td>Costos por-stride / por-window / freeze / cplF en Bellinge; proyecta 48 h de wall time</td><td>sin args</td></tr><tr><td><code>bench-1d.mjs</code></td><td>Benchmark 1D de stride puro; salida JSON</td><td><code>node bench-1d.mjs &lt;inp&gt; [--wasm &lt;path&gt;] [--tag &lt;l&gt;] [--keep-vs]</code></td></tr><tr><td><code>probe-1d.mjs</code></td><td>Volcado de head/depth por paso de uniones (limitado a 80 pasos)</td><td><code>node probe-1d.mjs &lt;inp&gt;</code></td></tr><tr><td><code>probe-1d-coupl.mjs</code></td><td>Carga 1D tipo split: <code>setPondArea</code> + <code>setLatInflow</code> alternado; histograma de dt</td><td>sin args (fixture Bellinge)</td></tr><tr><td><code>probe-1d-nan.mjs</code></td><td>Corrida 1D completa de 48 h escaneando heads/depths/volúmenes por NaN/Inf</td><td><code>node probe-1d-nan.mjs [VS]</code></td></tr><tr><td><code>probe-cpl.mjs</code></td><td>Deltas de volumen de acople por-stride desde el buffer de balance de masa de 10 slots</td><td><code>node probe-cpl.mjs &lt;inp&gt;</code></td></tr><tr><td><code>run-engine-marcher.mjs</code></td><td>Corrida 2D de referencia: depth/head/velocity por frame + heads de nodos + balance de masa → JSON. Requiere un build wasm <strong>sin hilos</strong> (el build con hilos necesita un navegador)</td><td><code>node run-engine-marcher.mjs &lt;inp&gt; &lt;out.json&gt; [--frames N] [--interval &lt;sec&gt;] [--wasm &lt;p&gt;]</code></td></tr><tr><td><code>bench-wasm-threads.mjs</code></td><td><strong>Gate del motor con hilos:</strong> ejecuta el <code>openSwmm2dWorker.js</code> de producción en Chrome con aislamiento cross-origin a THREADS 1 vs N; reporta wall time + continuidad bit-idéntica</td><td>CDP 9225</td></tr></tbody></table><h2 id="generadores-de-input-sintetico" tabindex="-1">Generadores de input sintético <a class="header-anchor" href="#generadores-de-input-sintetico" aria-label="Permalink to &quot;Generadores de input sintético&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Propósito</th><th>Uso</th></tr></thead><tbody><tr><td><code>make-marcher-inp.mjs</code></td><td>INP 2D M1 de cuenca cerrada (bordes WALL, lecho sinusoidal)</td><td><code>node make-marcher-inp.mjs &lt;nx&gt; &lt;ny&gt; &lt;dx&gt; &lt;rainMmHr&gt; &lt;min&gt; &lt;out.inp&gt;</code></td></tr><tr><td><code>make-marcher-cpl-inp.mjs</code></td><td>INP de acople 1D↔2D M2 (storage S1 + conducto + outfall, celda 0 acoplada)</td><td><code>node make-marcher-cpl-inp.mjs &lt;out.inp&gt;</code></td></tr></tbody></table><h2 id="harnesses-end-to-end-chrome-cdp" tabindex="-1">Harnesses end-to-end Chrome/CDP <a class="header-anchor" href="#harnesses-end-to-end-chrome-cdp" aria-label="Permalink to &quot;Harnesses end-to-end Chrome/CDP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Propósito</th><th>Puerto</th><th>Uso</th></tr></thead><tbody><tr><td><code>verify-bellinge.mjs</code></td><td><strong>Gate insignia:</strong> Chrome headless carga la app, proyecta Bellinge a EPSG:25832, auto-carga <code>Bellinge2.tif</code>, genera la malla, corre el modelo completo de 48 h a través del propio worker de la app, y verifica frames/depths/balance de masa/continuidad</td><td>CDP 9222</td><td>sin args; escribe <code>scripts/verify-out/</code></td></tr><tr><td><code>verify-1d-split.mjs</code></td><td>Gate de regresión para la pierna 1D del split (usa el <code>couplingSplit.js</code> de producción; falla ante heads de acople no finitos)</td><td>—</td><td><code>node verify-1d-split.mjs &lt;inp&gt; [--wasm &lt;p&gt;] [--tol &lt;%&gt;] [--hours &lt;n&gt;] [--json]</code></td></tr><tr><td><code>test-gpu-worker.mjs</code></td><td>Maneja el <code>gpu2dWorker.js</code> de producción a través del contrato <code>run2d</code> de la app en Chrome con ventana</td><td>CDP 9224</td><td><code>node test-gpu-worker.mjs [--inp &lt;p&gt;]</code></td></tr><tr><td><code>bench-gpu-coupl.mjs</code></td><td>Timings del split GPU por-window (<code>strideMs/freezeMs/advanceMs/exchMs/dt0/substeps</code>), extrapola 48 h de wall time</td><td>CDP 9225</td><td><code>node bench-gpu-coupl.mjs [--windows N] [--lts N] [--cadence N] [--dtfloor N] [--dbgcell N] [--inp &lt;p&gt;]</code></td></tr><tr><td><code>run-webgpu-harness.mjs</code></td><td>Maneja la paridad M1/M2 de <code>public/webgpu/harness.html</code> + bench en Chrome <strong>con ventana</strong> (headless no tiene WebGPU); prepara fixtures en <code>public/webgpu/fixtures/</code> desde <code>scripts/verify-out/</code></td><td>CDP 9223</td><td><code>node run-webgpu-harness.mjs [fixture…] [--coupled] [--bench] [--lts N] [--hours N]</code></td></tr><tr><td><code>test-2d-render.mjs</code></td><td>Smoke test del pipeline de render: flechas de velocidad, regresión de bandas de contorno, frame-max robusto, compilación de shaders WebGL2, finitud de <code>display2DResults</code></td><td>CDP 9225</td><td>sin args</td></tr></tbody></table><h2 id="scripts-de-build" tabindex="-1">Scripts de build <a class="header-anchor" href="#scripts-de-build" aria-label="Permalink to &quot;Scripts de build&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Propósito</th><th>Uso</th></tr></thead><tbody><tr><td><code>build-openswmm2d.sh</code></td><td>Build WASM para Linux/macOS (emcmake + vcpkg)</td><td><code>npm run build:2d-wasm:sh</code></td></tr><tr><td><code>build-openswmm2d.ps1</code></td><td>Build WASM para Windows</td><td><code>npm run build:2d-wasm</code></td></tr></tbody></table><h2 id="nota-sobre-fixtures" tabindex="-1">Nota sobre fixtures <a class="header-anchor" href="#nota-sobre-fixtures" aria-label="Permalink to &quot;Nota sobre fixtures&quot;">​</a></h2><blockquote><p><strong>Nota:</strong> <code>public/webgpu/fixtures/</code> <strong>no está commiteado</strong> — los scripts de harness lo generan/preparan desde <code>scripts/verify-out/</code>. Si falta un fixture, ejecuta primero el generador (<code>make-marcher-*.mjs</code>) o <code>verify-bellinge.mjs</code>.</p></blockquote>',13)])])}const u=t(a,[["render",s]]);export{m as __pageData,u as default};
